input.script:
phase("调研");
const first = agent("调研员甲").ask("E2E_DWR_TASK_A 调研第一份材料，给出一句结论。");
const second = agent("调研员乙").ask("E2E_DWR_TASK_B 调研第二份材料，给出一句结论。");
